def solve(di):
    H = len(di); W = len(di[0])
    # connected components of non-(0,2) cells (8-connectivity)
    seen = set(); objs = []
    for i in range(H):
        for j in range(W):
            if di[i][j] not in (0, 2) and (i, j) not in seen:
                col = di[i][j]; stack = [(i, j)]; comp = []; seen.add((i, j))
                while stack:
                    a, b = stack.pop()
                    comp.append((a, b))
                    for da in (-1, 0, 1):
                        for db in (-1, 0, 1):
                            x, y = a + da, b + db
                            if 0 <= x < H and 0 <= y < W and di[x][y] == col and (x, y) not in seen:
                                seen.add((x, y)); stack.append((x, y))
                objs.append((col, comp))
    # locate the wall: full line of 2s
    fr = [i for i in range(H) if all(c == 2 for c in di[i])]
    fwc = [j for j in range(W) if all(di[i][j] == 2 for i in range(H))]
    out = [[0] * W for _ in range(H)]
    wcells = set()
    if fr:
        fr_row = fr[0]; dr = -1 if fr_row > (H - 1 - 1) else -1
        # gravity direction: objects fall TOWARD wall row? In p1 expected: objects rest ABOVE floor row9... 
        # Check p1: floor at row9, objects end stacked above it (rows 6-8). So they fall DOWNWARD onto floor.
        dr = 1
        wcells = {(fr_row, c) for c in range(W)}
    elif fwc:
        fc = fwc[0]; dc = -1
        wcells = {(r, fc) for r in range(H)}
    else:
        return None
    if fwc:
        # horizontal wall: slide toward it (rightward if wall on right? p2 wall col0 -> slide LEFT toward it)
        dirc = -1 if fc == 0 else 1
        objs.sort(key=lambda o: (min(b for _, b in o[1]), o[0]))
    else:
        # vertical: p1 objects end stacked below their start toward floor row; floor row is bottom-ish? test both directions
        dirs = [1, -1]
        # choose direction such that gravity pulls down onto floor when floor near bottom
        dr = 1 if fr_row == H - 1 else -1
        objs.sort(key=lambda o: (max(a for a, _ in o[1]), o[0]))
        def spt(cells): return [(a + dr, b) for a, b in cells]
    def blocked(cells):
        return any(not(0 <= a < H and 0 <= b < W) or (a, b) in wcells or out[a][b] != 0 for a, b in cells)
    if fwc:
        def spt(cells): return [(a, b + dirc) for a, b in cells]
    for col, comp in objs:
        cur = list(comp)
        while True:
            nxt = spt(cur)
            if blocked(nxt): break
            cur = nxt
        for a, b in cur: out[a][b] = col
    return out

