def solve(di):
    H=len(di); W=len(di[0])
    seen=set(); objs=[]
    for i in range(H):
        for j in range(W):
            if di[i][j] not in (0,2) and (i,j) not in seen:
                col=di[i][j]; st=[(i,j)]; comp=[(i,j)]; seen.add((i,j))
                while st:
                    a,b=st.pop()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and di[x][y]==col and (x,y) not in seen:
                                seen.add((x,y)); comp.append((x,y)); st.append((x,y))
                objs.append((col,comp))
    fr=[i for i in range(H) if all(c==2 for c in di[i])]
    fwc=[j for j in range(W) if all(di[i][j]==2 for i in range(H))]
    wcells={(f,c) for f,c in [(r,c) for r in range(H) for c in range(W)] if any(c==fr[0] and all(di[r][c]==2 for r in [0])) or True} if False else set()
    if fr:
        out=[[2 if i==fr[0] else 0 for _ in range(W)] for _ in range(H)]
        objs.sort(key=lambda o:(-max(a for a,_ in o[1]),o[0]))
        def nxt(cur): return [(a+1,b) for a,b in cur]
        def blk(cells): return any(out[a][b]==2 or out[a][b]!=0 for a,b in cells)
        for col,comp in objs:
            cur=list(comp)
            while blk([(a+1,b) for a,b in cur]): pass
            # loop properly
            while True:
                nxtc=nxt(cur)
                if blk(nxtc): break
                cur=nxtc
            for a,b in cur: out[a][b]=col
    else:
        fc=fwc[0]
        dirc=-1 if fc==0 else 1
        out=[[2 if j==fc else 0 for _ in range(W)] for _ in range(H)]
        objs.sort(key=lambda o:(-min(b for _,b in o[1]),o[0]))
        def blk(cells): return any(out[a][b]!=0 for a,b in cells)
        for col,comp in objs:
            cur=list(comp)
            while True:
                nxtc=[(a,b+dirc) for a,b in cur]
                if blk(nxtc): break
                cur=nxtc
            for a,b in cur: out[a][b]=col
    return out
